add_action( 'woocommerce_checkout_order_created', function( $order ) {
    if ( ! $order instanceof \WC_Order ) {
        return;
    }
    $referral_code = isset( $_COOKIE['terso_ref'] ) ? sanitize_text_field( wp_unslash( $_COOKIE['terso_ref'] ) ) : '';
    if ( $referral_code ) {
        $order->update_meta_data( '_terso_referral_code', $referral_code );
        $order->save();
    }
} );
